import{_ as o}from"./chunks/home.pc.ko.BuJHOLWU.js";import{_ as a}from"./chunks/maintenance-pwr.pc.ko.BZ22xKJ9.js";import{_ as e,o as r,c as s,a5 as n}from"./chunks/framework.BjM_ivYE.js";const i="/RBQ/images/app/dashboard-vision.pc.ko.png",f=JSON.parse('{"title":"카메라 영상 안 나옴","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/no-camera-view.md","filePath":"ko/manual/troubleshooting/no-camera-view.md","lastUpdated":1789720001000}'),d={name:"ko/manual/troubleshooting/no-camera-view.md"};function c(l,t,p,h,u,g){return r(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="카메라-영상-안-나옴" tabindex="-1">카메라 영상 안 나옴 <a class="header-anchor" href="#카메라-영상-안-나옴" aria-label="Permalink to &quot;카메라 영상 안 나옴&quot;">​</a></h1><p>로봇에는 연결됐는데 앱에 카메라 영상이 표시되지 않는 경우입니다. 아래 순서대로 확인하세요.</p><h2 id="source" tabindex="-1">1. 지금 보고 있는 소스 확인 <a class="header-anchor" href="#source" aria-label="Permalink to &quot;1. 지금 보고 있는 소스 확인 {#source}&quot;">​</a></h2><p>뷰포트가 <code>3D</code>를 보고 있으면 영상이 아니라 로봇의 3D 자세가 나옵니다 — 고장이 아닙니다.</p><p><img src="'+o+'" alt="뷰포트와 소스 이름"></p><p>뷰포트 <strong>위 가운데의 소스 이름</strong>을 탭해 목록을 열고 <code>전방</code> 같은 카메라 소스를 고릅니다. 목록에는 <strong>로봇이 실제로 보고한 카메라만</strong> 나오므로, 원하는 소스가 아예 없다면 그 카메라가 로봇에 잡히지 않은 것입니다 — 아래 2번으로 넘어가세요.</p><p>소스별 필요 장치는 <a href="/RBQ/ko/manual/gui/camera-vision.html">카메라·비전</a>에 정리되어 있습니다.</p><h2 id="vision-status" tabindex="-1">2. 비전 상태 확인 <a class="header-anchor" href="#vision-status" aria-label="Permalink to &quot;2. 비전 상태 확인 {#vision-status}&quot;">​</a></h2><p><strong>대시보드</strong>를 열고 <strong>비전</strong> 탭으로 갑니다 — <a href="/RBQ/ko/manual/gui/developer-mode.html">개발자 모드</a>에서만 보이는 탭입니다.</p><p><img src="'+i+'" alt="대시보드 비전 탭"></p><ul><li><strong>데몬 연결</strong>과 <strong>센서 수</strong>를 먼저 봅니다. 데몬이 붙어 있지 않으면 영상 경로 전체가 죽은 것입니다.</li><li><strong>비전 센서</strong> 표에서 각 센서의 <code>STATUS</code>와 <code>RGB / IR / 3D fps</code>를 확인합니다. fps가 0이면 그 센서에서 프레임이 나오지 않는 상태입니다.</li></ul><p>비전 프로그램을 직접 켜고 끄려면 <strong>정비 → 비전</strong>의 <code>Vision Programs</code>를 씁니다 (<a href="/RBQ/ko/manual/gui/maintenance.html">정비</a> 참고).</p><h2 id="power" tabindex="-1">3. 카메라 전원 확인 <a class="header-anchor" href="#power" aria-label="Permalink to &quot;3. 카메라 전원 확인 {#power}&quot;">​</a></h2><p>카메라 전원이 꺼져 있으면 목록에도 안 뜨고 영상도 없습니다.</p><p><img src="'+a+'" alt="정비 전원 화면"></p><p><strong>정비 → 전원 / 시스템</strong>에서 아래가 켜져 있는지 봅니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>무엇이 꺼지나</th></tr></thead><tbody><tr><td><code>카메라 (5V)</code></td><td>본체 비전 카메라 — 끄면 영상이 끊깁니다</td></tr><tr><td><code>Vision PC (12V)</code></td><td>비전 PC — 끄면 카메라·오디오와 이 화면의 텔레메트리 일부가 끊깁니다</td></tr><tr><td><code>CCTV (12V)</code> · <code>열화상 (12V)</code></td><td>PTZ 유닛의 컬러·열화상 카메라</td></tr></tbody></table><h2 id="resolution" tabindex="-1">4. 화질 낮춰 보기 <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;4. 화질 낮춰 보기 {#resolution}&quot;">​</a></h2><p>무선이 약하면 영상이 아예 안 뜨기도 합니다. 오른쪽 <strong>관측</strong> 카드의 <strong>해상도 타일</strong>을 탭해 <code>SQHD 540</code>이나 <code>절약 360</code>으로 낮춰 보세요.</p><h2 id="reconnect" tabindex="-1">5. 다시 연결 <a class="header-anchor" href="#reconnect" aria-label="Permalink to &quot;5. 다시 연결 {#reconnect}&quot;">​</a></h2><p>위가 모두 정상인데도 영상이 없으면 연결을 다시 맺습니다.</p><p>왼쪽 위 로고로 <strong>허브</strong>로 돌아가 로봇 이름(▾)을 탭하고, <strong>로봇 선택</strong>에서 로봇 줄을 탭해 다시 연결합니다. 점이 초록이 되고 상태줄이 <code>연결됨</code>으로 바뀌면 영상이 다시 나오는지 확인하세요.</p><h2 id="after-update" tabindex="-1">소프트웨어 업데이트 직후라면 <a class="header-anchor" href="#after-update" aria-label="Permalink to &quot;소프트웨어 업데이트 직후라면 {#after-update}&quot;">​</a></h2><p><strong>원인:</strong> 로봇 소프트웨어를 업데이트한 뒤 재부팅하지 않으면 비전 프로그램이 정상적으로 시작되지 않는 경우가 있습니다.</p><p><strong>해결:</strong> <strong>로봇을 재부팅</strong>합니다 — <strong>정비 → 전원 / 시스템</strong>의 <code>시스템 재부팅</code>.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>재부팅하면 모터 전원이 끊겨 로봇이 주저앉습니다. 먼저 <strong>앉힌 뒤</strong> 바닥에 앉아 있는지 확인하고, 재부팅이 끝날 때까지 로봇을 움직이지 마세요.</p></div></div><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p>위 1~5번 중 어디까지 확인했는지, 그리고 <strong>비전 센서</strong> 표에서 fps가 0이었던 센서가 있다면 어느 것인지 함께 알려주시면 확인이 빠릅니다.</p><p><strong>→ <a href="/RBQ/ko/manual/support/">기술지원 요청</a></strong></p>',29)])])}const k=e(d,[["render",c]]);export{f as __pageData,k as default};
